mapper.select:
SELECT a.*, , p.name as patient_name, d.name as doctor_name, d.title as doctor_title, dept.dept_name, s.clinic_room FROM appointment a LEFT JOIN patient p ON a.patient_id = p.user_id LEFT JOIN doctor d ON a.doctor_id = d.doctor_id LEFT JOIN department dept ON a.dept_id = dept.dept_id LEFT JOIN schedule s ON a.schedule_id = s.schedule_id WHERE a.deleted = 0 AND a.patient_id = #{patientId}
AND a.visit_status = #{status}
ORDER BY a.appt_time DESC

SELECT a.*, , p.name as patient_name, d.name as doctor_name, d.title as doctor_title, dept.dept_name, s.clinic_room FROM appointment a LEFT JOIN patient p ON a.patient_id = p.user_id LEFT JOIN doctor d ON a.doctor_id = d.doctor_id LEFT JOIN department dept ON a.dept_id = dept.dept_id LEFT JOIN schedule s ON a.schedule_id = s.schedule_id WHERE a.deleted = 0 AND a.doctor_id = #{doctorId} AND a.visit_date = #{visitDate}
AND a.visit_status = #{visitStatus}
ORDER BY a.queue_no ASC
